pub mod extent_record {
    use super::*;

    pub const LEN: usize = 56;
    pub const FILE_OFFSET: U64 = U64(0);
    /// Offset of the DATA block header.
    pub const BLOCK_OFFSET: U64 = U64(8);
    /// 1..=MAX_CHUNK_RAW.
    pub const RAW_LEN: U32 = U32(16);
    /// Reserved for PACK. MUST be 0.
    pub const OFFSET_IN_BLOCK: U32 = U32(20);
    pub const RAW_DIGEST: Bytes<32> = Bytes(24);
    /// (offset, length) of every field that MUST be zero.
    pub const RESERVED: &[(usize, usize)] = &[];
    /// (name, offset field position, length field position) of every heap reference.
    pub const HEAP_REFS: &[(&str, usize, usize)] = &[];
    /// (name, offset, length) of every field, in order.
    pub const FIELDS: &[(&str, usize, usize)] = &[("file_offset", 0, 8), ("block_offset", 8, 8), ("raw_len", 16, 4), ("offset_in_block", 20, 4), ("raw_digest", 24, 32)];
}

/// One extended attribute. Owner is implied by the inode_record whose range contains it.
pub mod xattr_record {
    use super::*;

    pub const LEN: usize = 24;
    /// Full name including namespace, e.g. user.foo.
    pub const NAME_OFF: U64 = U64(0);
    /// Linux VFS (getxattr) representation.
    pub const VALUE_OFF: U64 = U64(8);
    pub const NAME_LEN: U32 = U32(16);
    pub const VALUE_LEN: U32 = U32(20);
    /// (offset, length) of every field that MUST be zero.
    pub const RESERVED: &[(usize, usize)] = &[];
    /// (name, offset field position, length field position) of every heap reference.
    pub const HEAP_REFS: &[(&str, usize, usize)] = &[("name", NAME_OFF.0, NAME_LEN.0), ("value", VALUE_OFF.0, VALUE_LEN.0)];
    /// (name, offset, length) of every field, in order.
    pub const FIELDS: &[(&str, usize, usize)] = &[("name_off", 0, 8), ("value_off", 8, 8), ("name_len", 16, 4), ("value_len", 20, 4)];
}

/// A table inside the INDX payload. `record_len` is None for a table with no
/// defined record, whose count must be zero.
pub struct IndexTable {
    pub name: &'static str,
    pub record_len: Option<usize>,
    pub count_off: usize,
    pub count_len: usize,
}

/// Tables in on-disk order after the index header; the heap follows the last.
pub const INDEX_TABLES: &[IndexTable] = &[
    IndexTable { name: "chain", record_len: Some(chain_record::LEN), count_off: 20, count_len: 4 },
    IndexTable { name: "inode", record_len: Some(inode_record::LEN), count_off: 56, count_len: 8 },
    IndexTable { name: "dir", record_len: Some(dir_record::LEN), count_off: 64, count_len: 8 },
    IndexTable { name: "dirent", record_len: Some(dirent_record::LEN), count_off: 72, count_len: 8 },
    IndexTable { name: "extent", record_len: Some(extent_record::LEN), count_off: 80, count_len: 8 },
    IndexTable { name: "xattr", record_len: Some(xattr_record::LEN), count_off: 88, count_len: 8 },
    IndexTable { name: "tombstone", record_len: None, count_off: 96, count_len: 8 },
];

/// Verification phases, in the order a reader performs them.
pub const PHASES: &[&str] = &["envelope", "trailer", "index_seal", "index_structure", "index_semantics", "blocks", "chain"];
